-- The rest of the Palms Off Gaming catalogue: 51 product lines across 13
-- categories (everything in the `palms off gaming products` bucket except
-- BINDERS, which shipped in 20260825014051).
--
-- One row per product LINE, not per SKU. A line's colour variants share a page
-- and a row; `sku` holds the line key (e.g. GCC-M) and the individual SKUs are
-- recorded in data/palmsOffCatalogue.js so per-colour stock can be attached
-- later without reshaping this table.
--
-- Seeded as `draft` with price 0, exactly like the binders: these are
-- enquiry-only until priced. Draft keeps them out of the shop grid (every shop
-- query filters status = 'active') so nothing shows as $0.00, while the
-- /shop/palms-off-gaming pages render from the committed catalogue and stay
-- indexable. Setting a price and flipping a row to 'active' in /admin/products
-- is all that is needed to turn Enquire now into Add to cart — the page and its
-- JSON-LD switch themselves.
--
-- Idempotent: keyed on the unique slug (index added in 20260825014051), so
-- re-running is a no-op and never overwrites prices or stock set in the admin.

insert into public.shop_products
  (title, slug, sku, description, images, brand, category, product_type, price_aud, stock_quantity, status)
select
  v.title, v.slug, v.sku, v.description, v.images::jsonb,
  'Palms Off Gaming', v.category, 'accessory', 0, 0, 'draft'
